import pytest

from llm_worker_pool.domain.token_estimate import (
    _CHARS_PER_TOKEN,
    estimate_tokens,
    max_chars_for_tokens,
)


@pytest.mark.parametrize(
    "text,expected_tokens",
    [
        ("", 0),                     # empty string
        ("a", 0),                     # less than one token
        ("abcd", 1),                  # exactly one token worth of chars
        ("abcdefgh", 2),              # two tokens
        ("abc def ghi jkl", 4),       # spaces counted as characters
        ("😀" * 8, 2),                # multibyte characters still count as Python chars
    ],
)
def test_estimate_tokens(text: str, expected_tokens: int):
    assert estimate_tokens(text) == expected_tokens


@pytest.mark.parametrize(
    "tokens,expected_chars",
    [
        (0, 0),
        (1, _CHARS_PER_TOKEN),
        (2, 2 * _CHARS_PER_TOKEN),
        (5, 5 * _CHARS_PER_TOKEN),
    ],
)
def test_max_chars_for_tokens(tokens: int, expected_chars: int):
    assert max_chars_for_tokens(tokens) == expected_chars


def test_inverse_relationship():
    """Check that the two functions are inverses for a range of token counts."""
    for tokens in range(0, 20):
        chars = max_chars_for_tokens(tokens)
        # estimate_tokens uses floor division, so we expect it to return the original token count
        # when the character count is exactly tokens * _CHARS_PER_TOKEN.
        assert estimate_tokens(chars) == tokens
